#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_prepend_resize_failure(void) {
    // Setup: create a buffer with small capacity and some initial data
    // We want self->len <= needed so that resize is required
    // helper_make_buffer_with_data is not in the operation map, so use buffer_new_with_copy
    buffer_t *buf = buffer_new_with_copy("world");
    TEST_ASSERT_NOT_NULL(buf);

    // Shrink the buffer's capacity to exactly fit the initial data (simulate small buffer)
    // buffer->len is the allocated size, buffer_length(buf) is strlen(buf->data)
    // Let's set len = strlen("world") = 5
    // (Assume buffer_new_with_copy sets len = 5)
    // Now, prepending "hello" (len=5) will require needed = 5+5 = 10, so resize is needed

    // Fail the next allocation after the 2 setup allocations (buffer_new_with_copy does 2 allocs)
    malloc_fail_after(2); // 2 setup allocs, then fail the realloc in buffer_resize

    int ret = buffer_prepend(buf, "hello");
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // The buffer should still be valid, but unchanged
    helper_assert_buffer_data_equals(buf, "world");
    helper_assert_buffer_length(buf, 5);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_resize_failure);
    return UNITY_END();
}


